def transform(grid):
    height = len(grid) // 4
    width = len(grid[0])
    out = [[0] * width for _ in range(height)]
    for band in range(4):
        for r in range(height):
            for c in range(width):
                value = grid[band * height + r][c]
                if out[r][c] == 0 and value != 0:
                    out[r][c] = value
    return out
